import { v4 as uuidv4 } from 'uuid';

export const addNotification = (data) => ({
    type: 'ADD_NOTIFICATION',
    payload: {
        id: uuidv4(),
        timestamp: new Date().toISOString(),
        read: false,
        ...data
    }
});

export const markNotificationRead = (notificationId) => ({
    type: 'MARK_NOTIFICATION_READ',
    payload: notificationId
});

export const markAllNotificationsRead = () => ({
    type: 'MARK_ALL_READ'
});

export const clearNotifications = () => ({
    type: 'CLEAR_NOTIFICATIONS'
});

// Action to handle new message notifications
export const handleNewMessage = (message, currentPath) => (dispatch) => {
    // Only create notification if user is not in the messages page
    if (!currentPath.includes('/message')) {
        dispatch(addNotification({
            type: 'message',
            title: 'Tin nhắn mới',
            message: `${message.sender.fullName}: ${message.content}`,
            sender: message.sender,
            link: `/message/${message.sender.id}`
        }));
    }
}; 