import { useRef, useEffect } from 'react';
import useScript from '../../hooks/useScript';

// https://github.com/anthonyjgrove/react-google-login/issues/502
// https://developers.google.com/identity/gsi/web/reference/js-reference#CredentialResponse
export default function GoogleLogin({
    onGoogleSignIn = () => { },
    text = 'signin_with',
}) {
    const googleSignInButton = useRef(null);

    useScript('https://accounts.google.com/gsi/client', () => {
        // https://developers.google.com/identity/gsi/web/reference/js-reference#google.accounts.id.initialize
        window.google.accounts.id.initialize({
            client_id: process.env.REACT_APP_GOOGLE_CLIENT_ID,
            callback: onGoogleSignIn,
            // Add proper popup settings
            ux_mode: 'popup',
            context: 'signin',
        });
        // https://developers.google.com/identity/gsi/web/reference/js-reference#google.accounts.id.renderButton
        window.google.accounts.id.renderButton(
            googleSignInButton.current,
            {
                theme: 'filled_blue',
                size: 'large',
                text,
                width: '250',
                type: 'standard',
            }, // customization attributes
        );
    });

    // Add click handler to manually handle popup
    useEffect(() => {
        const handleButtonClick = () => {
            window.google?.accounts.id.prompt((notification) => {
                if (notification.isNotDisplayed() || notification.isSkippedMoment()) {
                    console.log('Google One Tap is not displayed or skipped', notification);
                }
            });
        };

        const buttonElement = googleSignInButton.current?.querySelector('button');
        if (buttonElement) {
            // Remove default click handler and add our own
            const defaultOnClick = buttonElement.onclick;
            buttonElement.onclick = (e) => {
                e.preventDefault();
                handleButtonClick();
            };
        }

        return () => {
            // Cleanup if needed
            const buttonElement = googleSignInButton.current?.querySelector('button');
            if (buttonElement) {
                buttonElement.onclick = null;
            }
        };
    }, [googleSignInButton.current]);

    return <div ref={googleSignInButton}></div>;
}
