import axios from "axios";

// Define API base URL with fallback
export const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:8080";

// Create axios instance with default config
export const api = axios.create({
    baseURL: API_BASE_URL,
    headers: {
        "Content-Type": "application/json"
    },
    timeout: 15000 // 15 seconds timeout
});

// Add auth token to every request
api.interceptors.request.use(
    config => {
        const token = localStorage.getItem("jwt");
        if (token) {
            config.headers["Authorization"] = `Bearer ${token}`;
        }
        return config;
    },
    error => Promise.reject(error)
);

// Configure WebSocket options
export const webSocketConfig = {
    // Disable debug logs in production
    debug: process.env.NODE_ENV !== 'production',
    // Reconnect settings
    reconnectDelay: 5000,
    reconnectDelayMax: 30000,
    // Heartbeat settings to keep connection alive
    heartbeatIncoming: 4000,
    heartbeatOutgoing: 4000,
    // Connection timeout
    connectTimeout: 10000,
    // Add CORS support
    connectHeaders: {
        "Origin": window.location.origin
    }
};

// Helper function to create WebSocket URL with proper fallback
export const getWebSocketUrl = () => {
    // If API is on the same origin, use relative path to benefit from same auth cookies
    if (API_BASE_URL.startsWith(window.location.origin) || API_BASE_URL === 'http://localhost:8080') {
        return `${API_BASE_URL}/ws`;
    }

    // Otherwise, use full URL with ws/wss protocol
    const wsProtocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const baseUrl = API_BASE_URL.replace(/^https?:/, wsProtocol);
    return `${baseUrl}/ws`;
};
