import React, { useEffect, useState } from 'react';
import { navigationMenu } from './NavigationMenu';
import { useNavigate } from 'react-router-dom';
import { Avatar, Badge, Button, Menu, MenuItem, IconButton, Tooltip } from '@mui/material';
import { MoreHoriz } from '@mui/icons-material';
import logo from '../../images/avatar/logo.png';
import { useDispatch, useSelector } from 'react-redux';
import { logout } from '../../Store/Auth/Action';
import { useTheme } from '../../theme/ThemeContext';
import Brightness4Icon from '@mui/icons-material/Brightness4';
import Brightness7Icon from '@mui/icons-material/Brightness7';

function Navigation() {
    const { auth } = useSelector(store => store);
    const dispatch = useDispatch();
    const unreadMessages = useSelector(store => store.chat.unreadMessages || 0);
    const unreadNotifications = useSelector(state => state.notification.unreadCount || 0);
    const navigate = useNavigate();
    const [anchorEl, setAnchorEl] = useState(null);
    const open = Boolean(anchorEl);
    const { isDarkMode, toggleTheme } = useTheme();

    const handleClick = (e) => {
        setAnchorEl(e.currentTarget);
    };
    const handleClose = () => {
        setAnchorEl(null);
    };
    const handleLogout = () => {
        dispatch(logout());
        handleClose();
    };

    if (!auth?.user) {
        return null;
    }

    const renderMenuItem = (item) => {
        if (item.title === 'Tin nhắn') {
            return (
                <Badge badgeContent={unreadMessages} color="error">
                    {item.icon}
                </Badge>
            );
        }
        if (item.title === 'Thông báo') {
            return (
                <Badge badgeContent={unreadNotifications} color="error">
                    {item.icon}
                </Badge>
            );
        }
        return item.icon;
    };

    const filteredMenu = navigationMenu.filter(item =>
        !item.adminOnly || (item.adminOnly && auth.user.isAdmin)
    );

    return (
        <div className='h-screen sticky top-0'>
            <div>
                <div className='py-5 flex items-center justify-between'>
                    <img src={logo} alt="logo" className='w-[60px] h-[60px] rounded-full' />
                    <Tooltip title={isDarkMode ? "Chế độ sáng" : "Chế độ tối"}>
                        <IconButton onClick={toggleTheme} sx={{ ml: 1 }}>
                            {isDarkMode ? <Brightness7Icon /> : <Brightness4Icon />}
                        </IconButton>
                    </Tooltip>
                </div>
                <div className='space-y-6 mt-4'>
                    {filteredMenu.map((item) => (
                        <div
                            key={item.path}
                            className='cursor-pointer flex space-x-3 items-center'
                            onClick={() => navigate(item.path)}
                        >
                            {renderMenuItem(item)}
                            <p className='text-xl'>{item.title}</p>
                        </div>
                    ))}
                </div>
            </div>

            <div className='flex items-center justify-between ' style={{ marginTop: '160px' }}>
                <div className='flex items-center space-x-3'>
                    <Avatar
                        alt={auth.user.fullName || 'User'}
                        src={auth.user.image || '/default-avatar.png'}
                        onClick={() => navigate("/account")}
                    />
                    <div>
                        <p>{auth.user.fullName}</p>
                        <span className='opacity-70'>
                            @{auth.user.fullName ? auth.user.fullName.split(" ").join("_").toLowerCase() : "unknown_user"}
                        </span>
                    </div>
                    <Button
                        id="demo-positioned-button"
                        aria-controls={open ? 'demo-positioned-menu' : undefined}
                        aria-haspopup="true"
                        aria-expanded={open ? 'true' : undefined}
                        onClick={handleClick}
                    >
                        <MoreHoriz />
                    </Button>
                    <Menu
                        id="demo-positioned-menu"
                        aria-labelledby="demo-positioned-button"
                        anchorEl={anchorEl}
                        open={open}
                        onClose={handleClose}
                        anchorOrigin={{
                            vertical: 'top',
                            horizontal: 'left',
                        }}
                        transformOrigin={{
                            vertical: 'top',
                            horizontal: 'left',
                        }}
                    >
                        <MenuItem onClick={handleLogout}>Logout</MenuItem>
                    </Menu>
                </div>
            </div>
        </div>
    );
}

export default Navigation;
